mapper.select:
SELECT a.id, a.create_by AS createBy, a.create_date AS createDate, a.update_by AS updateBy, a.update_date AS updateDate, a.remarks, a.status, a.record_name AS recordName, a.warning_id AS warningId, a.warning_record AS warningRecord, a.alarm_time AS alarmTime, a.handler, a.handle_time AS handleTime, a.handle_process AS handleProcess, a.handle_status AS handleStatus, a.attachment, b.warning_content AS warningContent, b.person_name AS warningMan FROM swm_handle_record a LEFT JOIN swm_warning_management b ON a.warning_id = b.id
a.status = '0'
AND a.record_name LIKE concat('%', #{recordName}, '%')
AND a.warning_id = #{warningId}
AND a.warning_record LIKE concat('%', #{warningRecord}, '%')
AND b.warning_content = #{warningContent}
AND a.handler LIKE concat('%', #{handler}, '%')
AND a.handle_status = #{handleStatus}
AND a.alarm_time BETWEEN #{beginAlarmTime} AND #{endAlarmTime}
AND a.handle_time BETWEEN #{beginHandleTime} AND #{endHandleTime}
ORDER BY a.create_date DESC
